<script setup>defineProps({busy:Boolean,error:Object,empty:Boolean});defineEmits(['retry'])</script>
<template><section v-if="busy" class="state" role="status">Chargement des données…</section><section v-else-if="error" class="state" role="alert"><h2>{{ error.status===403?'Accès refusé':error.status===404?'Ressource introuvable':'Données indisponibles' }}</h2><p>{{ error.message }}</p><button class="secondary" @click="$emit('retry')">Réessayer</button></section><section v-else-if="empty" class="state"><h2>Aucun résultat dans ce périmètre</h2><p>Modifiez votre recherche ou vos filtres pour explorer d’autres données.</p></section><slot v-else/></template>
